export const GLOSSARY_SHARD = Object.freeze({"fully-diluted-valuation":{"slug":"fully-diluted-valuation","cat":"basics","en":"Fully diluted valuation (FDV)","contentLocale":"vi","term":"Định giá pha loãng hoàn toàn (FDV)","aka":["FDV","fully diluted valuation","vốn hóa pha loãng"],"short":"Định giá pha loãng hoàn toàn (FDV) là giá hiện tại của token nhân với tổng cung tối đa, cho biết dự án sẽ được định giá bao nhiêu nếu toàn bộ token đã được phát hành.","body":[["Nhiều dự án chỉ cho lưu hành một phần nhỏ token lúc ",["niêm yết","token-listing"],", phần còn lại dành cho đội ngũ, nhà đầu tư, quỹ hệ sinh thái và sẽ được mở khóa dần. ",["Vốn hóa","market-capitalization"]," chỉ tính phần đang lưu hành, còn FDV tính tất cả."],"Tỷ lệ vốn hóa trên FDV càng thấp thì lượng token còn chờ ra thị trường càng lớn. Khi các đợt mở khóa diễn ra, nếu nhu cầu không tăng theo, áp lực bán có thể kéo giá xuống. Đó là lý do người giao dịch hay nhắc đến token có vốn hóa thấp nhưng FDV cao.","FDV không phải dự báo giá. Nó là một phép tính giúp bạn hình dung quy mô thật sự của dự án. Với coin không có tổng cung tối đa cố định, mỗi trang dữ liệu có thể tính FDV theo cách khác nhau, nên hãy đọc kỹ cách họ định nghĩa."],"example":["Một token mới niêm yết có giá 0,5 ",["USDT","usdt"],", ",["nguồn cung lưu hành","circulating-supply"]," 150 triệu và tổng cung tối đa 1 tỷ. Vốn hóa là 75 triệu USDT, còn FDV là 500 triệu USDT. Chỉ 15% token đang lưu hành. Nếu 6 tháng sau có thêm 100 triệu token mở khóa và vốn hóa giữ nguyên 75 triệu USDT, giá sẽ phải giảm còn 75 triệu / 250 triệu = 0,3 USDT."],"mistakes":["Chỉ nhìn vốn hóa nhỏ mà không thấy FDV lớn gấp nhiều lần.","Nghĩ rằng FDV là mức giá mục tiêu mà token sẽ đạt tới.","Bỏ qua lịch mở khóa khi tỷ lệ vốn hóa trên FDV rất thấp."],"faq":[{"q":"FDV cao có phải là xấu?","a":"Không hẳn. FDV cao so với vốn hóa cho thấy còn nhiều token chưa phát hành, nên bạn cần xem token mở khóa khi nào và cho ai trước khi đánh giá."},{"q":"Bitcoin có FDV không?","a":"Có, FDV của Bitcoin là giá nhân 21 triệu BTC. Vì phần lớn BTC đã được đào, FDV và vốn hóa của Bitcoin khá gần nhau."}],"title":"FDV là gì? Định giá pha loãng hoàn toàn","description":"FDV là gì, khác vốn hóa thị trường ra sao và vì sao token có FDV cao so với vốn hóa cần được xem kỹ lịch mở khóa.","related":[["market-capitalization","Vốn hóa thị trường (Market cap)","Vốn hóa thị trường (market cap) của một đồng tiền mã hóa là giá hiện tại nhân với nguồn cung lưu hành, cho biết tổng giá trị thị trường đang định cho lượng coin đang lưu thông."],["circulating-supply","Nguồn cung lưu hành (Circulating supply)","Nguồn cung lưu hành (circulating supply) là số lượng coin hoặc token đang thực sự có trên thị trường và có thể giao dịch, không tính phần bị khóa, chưa phát hành hoặc đã bị đốt."],["token-unlock","Mở khóa token (Token unlock)","Mở khóa token (token unlock) là thời điểm một lượng token trước đây bị khóa theo lịch vesting được phép chuyển và bán, thường là phần của đội ngũ, nhà đầu tư hoặc quỹ dự án."],["tokenomics","Tokenomics (kinh tế học token)","Tokenomics là toàn bộ thiết kế kinh tế của một token: tổng cung, cách phân bổ, lịch mở khóa, cơ chế phát hành và đốt, cùng công dụng khiến người dùng cần giữ hoặc dùng token đó."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"mining":{"slug":"mining","cat":"basics","en":"Crypto mining","contentLocale":"vi","term":"Đào coin (Crypto mining)","aka":["đào coin","mining","khai thác tiền mã hóa","đào Bitcoin"],"short":"Đào coin (crypto mining) là quá trình dùng máy tính chuyên dụng giải bài toán mật mã để xác nhận giao dịch, thêm khối mới vào blockchain bằng chứng công việc và nhận coin mới làm phần thưởng.","body":[["Thợ đào gom các giao dịch đang chờ thành một khối rồi liên tục thử các giá trị để tìm mã băm hợp lệ. Ai tìm ra trước sẽ nhận phần thưởng khối cộng phí giao dịch. Với ",["Bitcoin","bitcoin"],", gần như chỉ máy ASIC chuyên dụng mới đào có lãi; card đồ họa (GPU) dùng cho một số coin ",["PoW","proof-of-work"]," khác."],"Lợi nhuận đào phụ thuộc vào giá coin, độ khó mạng, giá điện, hiệu suất máy và phí pool. Khi halving xảy ra hoặc độ khó tăng, thu nhập trên mỗi máy giảm. Vì thế nhiều thợ đào nhỏ gia nhập pool đào để chia thưởng theo sức đào đóng góp.","Hãy cẩn thận với các gói đào coin trên đám mây (cloud mining) hoặc ứng dụng đào trên điện thoại hứa lợi nhuận cố định. Nhiều dịch vụ kiểu này là lừa đảo hoặc có chi phí ẩn khiến lợi nhuận thực tế âm. Quy định về đào coin cũng khác nhau tùy quốc gia."],"example":"Giả sử một máy ASIC tiêu thụ 3 kW và chạy 24 giờ mỗi ngày, tức 72 kWh mỗi ngày. Với giá điện 0,08 USD mỗi kWh, chi phí điện là 5,76 USD mỗi ngày. Nếu máy tạo ra khoảng 0,00012 BTC mỗi ngày sau phí pool và BTC ở mức 60.000 USD, doanh thu là 7,2 USD. Lợi nhuận gộp chỉ còn 1,44 USD mỗi ngày, chưa tính khấu hao máy. Nếu độ khó tăng 10% hoặc giá BTC giảm 20%, máy có thể chuyển sang lỗ.","mistakes":["Tính lợi nhuận mà quên chi phí điện, làm mát và khấu hao máy.","Mua gói cloud mining hứa lãi cố định mỗi ngày mà không kiểm chứng được.","Nghĩ rằng có thể đào Bitcoin có lãi bằng laptop hoặc điện thoại."],"faq":[{"q":"Đào coin có còn lãi không?","a":"Tùy vào giá điện, loại máy, độ khó mạng và giá coin tại thời điểm đó. Với Bitcoin, lợi nhuận thường chỉ đến với những nơi có điện rẻ và máy đời mới."},{"q":"Ethereum còn đào được không?","a":"Không. Từ tháng 9 năm 2022 Ethereum đã chuyển sang bằng chứng cổ phần, nên không còn đào ETH bằng GPU nữa."}],"title":"Đào coin là gì? Crypto mining hoạt động ra sao","description":"Đào coin là gì, thợ đào kiếm tiền thế nào, những chi phí cần tính và vì sao cần cảnh giác với cloud mining.","related":[["proof-of-work","Bằng chứng công việc (Proof of Work - PoW)","Bằng chứng công việc (Proof of Work, PoW) là cơ chế đồng thuận trong đó thợ đào dùng sức mạnh tính toán để giải bài toán mật mã, ai tìm ra lời giải trước sẽ được thêm khối mới và nhận thưởng."],["hash-rate","Hash rate (tốc độ băm)","Hash rate là tổng sức mạnh tính toán mà các máy đào dùng để bảo vệ một blockchain proof of work, đo bằng số phép băm mỗi giây."],["bitcoin-halving","Bitcoin halving (sự kiện giảm một nửa)","Bitcoin halving là sự kiện được lập trình sẵn, cứ mỗi 210.000 khối (khoảng 4 năm) thì phần thưởng khối cho thợ đào giảm đi một nửa, làm chậm tốc độ phát hành BTC mới."],["blockchain","Blockchain (chuỗi khối)","Blockchain (chuỗi khối) là một sổ cái số được chia sẻ, trong đó các giao dịch được gom thành từng khối và nối với nhau theo thứ tự, nên muốn sửa dữ liệu cũ thì phải làm lại toàn bộ các khối phía sau."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"validator":{"slug":"validator","cat":"basics","en":"Validator","contentLocale":"vi","term":"Validator (trình xác thực)","aka":["trình xác thực","node xác thực","validator"],"short":"Validator (trình xác thực) là node trên blockchain bằng chứng cổ phần, khóa coin làm tài sản đảm bảo để đề xuất, kiểm tra và bỏ phiếu cho các khối mới, đổi lại nhận phần thưởng.","body":[["Trong mạng ",["PoS","proof-of-stake"],", validator đóng vai trò tương tự thợ đào trong mạng ",["PoW","proof-of-work"],". Họ chạy phần mềm ",["node","node"]," liên tục, nhận giao dịch, đề xuất khối khi đến lượt và ",["xác nhận","block-confirmations"]," khối của người khác. Trên ",["Ethereum","ethereum"],", mỗi validator cần 32 ETH để kích hoạt."],"Validator kiếm thưởng khi làm đúng và có thể bị trừ thưởng nếu offline. Nếu vi phạm nghiêm trọng như ký hai khối mâu thuẫn, họ bị slashing, tức là mất một phần coin đã stake và có thể bị buộc rời mạng.","Nhiều mạng như Solana, Cosmos hay Polkadot cho phép bạn ủy quyền (delegate) coin cho validator mà không mất quyền sở hữu. Bạn chia sẻ phần thưởng và cả rủi ro bị phạt của validator đó, sau khi họ trừ phí hoa hồng. Vì vậy chọn validator có thời gian hoạt động cao và phân tán là điều quan trọng."],"example":"Giả sử bạn ủy quyền 1.000 coin cho một validator trên mạng có mức thưởng khoảng 7% mỗi năm. Trước phí, bạn có thể nhận khoảng 70 coin. Validator thu hoa hồng 8%, nên bạn còn khoảng 64,4 coin. Nếu validator này bị slashing 1% vì lỗi ký đôi, bạn mất 10 coin trong số đã ủy quyền, tức phần thưởng ròng còn khoảng 54,4 coin cho năm đó. Mức phạt cụ thể khác nhau theo từng mạng.","mistakes":["Chọn validator có hoa hồng 0% mà không kiểm tra thời gian online và lịch sử bị phạt.","Dồn toàn bộ stake vào một validator thay vì chia ra vài validator uy tín.","Nghĩ rằng ủy quyền nghĩa là chuyển coin cho validator giữ hộ."],"faq":[{"q":"Muốn làm validator Ethereum cần bao nhiêu ETH?","a":"Mỗi validator Ethereum cần 32 ETH cùng phần cứng chạy liên tục. Nếu có ít hơn, bạn có thể dùng staking qua sàn hoặc liquid staking."},{"q":"Validator có lấy được coin của người ủy quyền không?","a":"Với cơ chế ủy quyền gốc của mạng, validator không thể chuyển coin của bạn đi. Tuy vậy bạn vẫn chịu chung rủi ro bị phạt nếu validator vi phạm."}],"title":"Validator là gì? Vai trò trong mạng PoS","description":"Validator là gì, vì sao Ethereum cần 32 ETH, slashing hoạt động ra sao và cách chọn validator khi ủy quyền coin.","related":[["proof-of-stake","Bằng chứng cổ phần (Proof of Stake - PoS)","Bằng chứng cổ phần (Proof of Stake, PoS) là cơ chế đồng thuận trong đó validator khóa coin của mạng làm tài sản đảm bảo để được quyền đề xuất và xác thực khối mới, thay cho việc đào bằng máy."],["staking","Staking","Staking là việc khóa coin của một blockchain proof-of-stake để giúp xác thực giao dịch và bảo vệ mạng lưới, đổi lại nhận phần thưởng bằng chính coin đó."],["restaking","Restaking (Tái staking)","Restaking là việc dùng lại ETH đã stake hoặc token stake thanh khoản để bảo đảm an ninh thêm cho các dịch vụ khác, nhận thêm phần thưởng nhưng chịu thêm rủi ro bị phạt."],["blockchain","Blockchain (chuỗi khối)","Blockchain (chuỗi khối) là một sổ cái số được chia sẻ, trong đó các giao dịch được gom thành từng khối và nối với nhau theo thứ tự, nên muốn sửa dữ liệu cũ thì phải làm lại toàn bộ các khối phía sau."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"trading-pair":{"slug":"trading-pair","cat":"trading","en":"Trading pair","contentLocale":"vi","term":"Cặp giao dịch (Trading pair)","aka":["cặp giao dịch","trading pair","cặp tiền"],"short":"Cặp giao dịch (trading pair) là hai tài sản được mua bán trực tiếp với nhau trên sàn, ví dụ BTC/USDT, trong đó đồng đứng trước là tài sản cơ sở và đồng đứng sau là đồng định giá.","body":[["Trong cặp ",["BTC","bitcoin"],"/",["USDT","usdt"],", BTC là tài sản cơ sở (base) và USDT là đồng định giá (quote). Giá 60.000 nghĩa là 1 BTC đổi được 60.000 USDT. Khi bạn mua cặp này, bạn dùng USDT để mua BTC; khi bán, bạn đổi BTC lấy USDT."],["Các đồng định giá phổ biến là USDT, ",["USDC","usdc"],", BTC và đôi khi tiền pháp định. Cùng một coin có thể có nhiều cặp, như SOL/USDT, SOL/USDC, SOL/BTC, mỗi cặp có ",["sổ lệnh","order-book"]," và ",["thanh khoản","liquidity"]," riêng. Cặp có USDT thường có khối lượng lớn nhất trên nhiều sàn."],["Chọn cặp có thanh khoản cao giúp bạn có ",["chênh lệch giá mua-bán","bid-ask-spread"]," hẹp và ít trượt giá. Với cặp định giá bằng BTC, lãi lỗ của bạn tính bằng BTC, nên kết quả quy ra USD còn phụ thuộc vào giá BTC."]],"example":"Giả sử SOL/USDT đang ở 150 và BTC/USDT ở 60.000, nên SOL/BTC xấp xỉ 150 / 60.000 = 0,0025. Bạn mua 4 SOL bằng cặp SOL/BTC, trả 0,01 BTC. Sau đó SOL tăng lên 165 USDT (tăng 10%) nhưng BTC cũng tăng lên 66.000 (tăng 10%). Tính bằng USDT, phần SOL của bạn tăng từ 600 lên 660 USDT, nhưng tính bằng BTC, nó vẫn là 4 × 165 / 66.000 = 0,01 BTC, không lời không lỗ.","mistakes":["Đặt lệnh trên cặp SOL/BTC trong khi nghĩ mình đang dùng USDT.","Chọn cặp có thanh khoản thấp và chịu chênh lệch giá lớn.","Đọc ngược giá, nhầm tài sản cơ sở với đồng định giá."],"faq":[{"q":"BTC/USDT nghĩa là gì?","a":"Đó là cặp giao dịch Bitcoin định giá bằng USDT. Giá hiển thị cho biết cần bao nhiêu USDT để mua 1 BTC."},{"q":"Vì sao cùng một coin lại có giá hơi khác nhau ở các cặp?","a":"Mỗi cặp có sổ lệnh riêng, nên giá có thể lệch nhẹ. Nhà kinh doanh chênh lệch giá (arbitrage) thường kéo các mức giá này về gần nhau."}],"title":"Cặp giao dịch là gì? Cách đọc BTC/USDT","description":"Cặp giao dịch là gì, cách đọc tài sản cơ sở và đồng định giá, và vì sao chọn cặp có thanh khoản cao giúp giảm trượt giá.","related":[["spot-trading","Giao dịch spot (Spot trading)","Giao dịch spot (spot trading) là mua bán tài sản crypto để nhận ngay quyền sở hữu thật ở giá hiện tại, không dùng hợp đồng và mặc định không có đòn bẩy."],["order-book","Sổ lệnh (Order book)","Sổ lệnh (order book) là danh sách theo thời gian thực của tất cả lệnh mua và lệnh bán đang chờ khớp cho một cặp giao dịch, sắp xếp theo mức giá và khối lượng."],["liquidity","Thanh khoản (Liquidity)","Thanh khoản là mức độ dễ dàng mua hoặc bán một tài sản với số lượng lớn mà giá không bị đẩy đi nhiều."],["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"Giao dịch spot đầu tiên: Từ 100 đến 0.002 BTC"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"oco-order":{"slug":"oco-order","cat":"trading","en":"OCO order (one-cancels-the-other)","contentLocale":"vi","term":"Lệnh OCO (One-cancels-the-other)","aka":["OCO","lệnh OCO","one cancels the other"],"short":"Lệnh OCO (one-cancels-the-other) là cặp hai lệnh được đặt cùng lúc, thường một chốt lời và một cắt lỗ; khi một lệnh khớp hoặc kích hoạt, lệnh còn lại tự động bị hủy.","body":[["Trên ",["thị trường spot","spot-trading"],", OCO thường gồm một ",["lệnh giới hạn","limit-order"]," ở trên giá hiện tại để ",["chốt lời","take-profit"]," và một ",["lệnh stop-limit","stop-limit-order"]," ở dưới để ",["cắt lỗ","stop-loss"],". Cả hai dùng chung số coin, nên khi một bên khớp, bên kia bị hủy để bạn không bán hai lần."],"OCO hữu ích khi bạn không thể theo dõi thị trường liên tục: bạn đặt sẵn kịch bản thắng và kịch bản thua rồi để hệ thống thực thi. Trên giao dịch hợp đồng, chức năng tương tự thường là gắn TP/SL vào vị thế.","Nếu giá chỉ chạm một phần lệnh chốt lời, lệnh có thể khớp một phần và lệnh cắt lỗ còn lại sẽ được điều chỉnh hoặc hủy tùy quy tắc từng sàn. Phần cắt lỗ thường là stop-limit nên vẫn có rủi ro không khớp khi giá rơi quá nhanh."],"example":["Bạn mua 10 LINK ở 15 ",["USDT","usdt"],", tổng 150 USDT. Bạn đặt OCO bán 10 LINK: phần chốt lời là lệnh giới hạn ở 18 USDT; phần cắt lỗ kích hoạt ở 13,5 với giới hạn 13,4. Nếu giá lên 18, bạn bán được 180 USDT, lãi 30 USDT, và lệnh cắt lỗ tự hủy. Nếu giá giảm về 13,5 trước, lệnh cắt lỗ khớp quanh 134 đến 135 USDT, lỗ khoảng 15 đến 16 USDT, và lệnh chốt lời tự hủy."],"mistakes":["Đặt giá chốt lời thấp hơn giá hiện tại, khiến phần giới hạn khớp ngay.","Quên rằng phần cắt lỗ là stop-limit và có thể không khớp khi giá rơi mạnh.","Đặt riêng hai lệnh chốt lời và cắt lỗ thay vì OCO, rồi lo cả hai cùng khóa số coin."],"faq":[{"q":"OCO nghĩa là gì?","a":"OCO là viết tắt của one-cancels-the-other, nghĩa là một lệnh khớp thì lệnh kia bị hủy. Nó giúp bạn đặt cùng lúc chốt lời và cắt lỗ cho cùng một lượng coin."},{"q":"Sàn nào có lệnh OCO?","a":"Nhiều sàn tập trung lớn hỗ trợ OCO trên thị trường spot, nhưng tên gọi và quy tắc chi tiết khác nhau. Hãy xem phần loại lệnh trong ứng dụng sàn bạn dùng."}],"title":"Lệnh OCO là gì? Cách đặt chốt lời và cắt lỗ","description":"Lệnh OCO là gì, cách kết hợp chốt lời và cắt lỗ trong một lệnh, ví dụ cụ thể và những lưu ý khi giá biến động mạnh.","related":[["take-profit","Lệnh chốt lời (Take-profit)","Lệnh chốt lời (take-profit) là lệnh tự động đóng toàn bộ hoặc một phần vị thế khi giá đạt mức lợi nhuận bạn đặt trước, giúp bạn khóa lãi mà không cần theo dõi màn hình liên tục."],["stop-loss","Lệnh cắt lỗ (Stop-loss)","Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng."],["limit-order","Lệnh giới hạn (Limit order)","Lệnh giới hạn (limit order) là lệnh mua hoặc bán ở mức giá bạn chỉ định hoặc tốt hơn; lệnh chỉ khớp khi thị trường chạm mức giá đó, nếu không sẽ nằm chờ trong sổ lệnh."],["risk-reward-ratio","Tỷ lệ rủi ro/lợi nhuận (Risk-reward ratio)","Tỷ lệ rủi ro/lợi nhuận (R:R) so sánh số tiền bạn có thể mất nếu chạm cắt lỗ với số tiền bạn có thể lãi nếu chạm chốt lời trong cùng một lệnh."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Thị trường, giới hạn, hủy lệnh: mỗi loại giải quyết điều gì?"},"coin":null,"tool":null,"cta":false},"post-only-order":{"slug":"post-only-order","cat":"trading","en":"Post-only order","contentLocale":"vi","term":"Lệnh chỉ đặt (Post-only)","aka":["post only","lệnh post-only","chỉ maker"],"short":"Lệnh post-only là lệnh giới hạn chỉ được chấp nhận nếu nó nằm chờ trong sổ lệnh làm maker; nếu lệnh sẽ khớp ngay và trở thành taker, sàn tự động hủy hoặc điều chỉnh nó.","body":["Khi bạn tích chọn post-only, sàn kiểm tra lệnh trước khi đưa vào sổ. Nếu giá của bạn khớp ngay với lệnh đối diện, ví dụ đặt mua ở giá cao hơn giá bán tốt nhất, lệnh bị từ chối. Một số sàn thay vì hủy sẽ đẩy giá về mức gần nhất không khớp ngay.",["Mục đích chính là đảm bảo bạn luôn được tính ",["phí maker","maker-taker-fees"],", thường thấp hơn phí taker và ở một số sàn hoặc cấp tài khoản có thể bằng không hoặc âm. Với người giao dịch thường xuyên hoặc ",["bot lưới","grid-trading-bot"],", chênh lệch phí này cộng dồn thành con số lớn."],"Đổi lại, bạn chấp nhận lệnh có thể không bao giờ khớp và phải đặt lại nhiều lần khi giá chạy nhanh. Post-only không phù hợp khi bạn cần vào hoặc thoát lệnh gấp."],"example":["Giả sử bạn giao dịch 200.000 ",["USDT","usdt"]," mỗi tháng. Nếu tất cả là lệnh taker với phí 0,05%, bạn trả 100 USDT. Nếu chuyển sang post-only với phí maker 0,02%, bạn trả 40 USDT, tiết kiệm 60 USDT mỗi tháng, tức 720 USDT mỗi năm. Nhưng nếu giá bán tốt nhất là 30.000 và bạn đặt post-only mua ở 30.005, lệnh sẽ bị hủy vì nó sẽ khớp ngay như taker."],"mistakes":["Bật post-only rồi thắc mắc vì sao lệnh liên tục bị hủy.","Dùng post-only để thoát vị thế khi giá đang chạy ngược mạnh.","Nghĩ rằng post-only đảm bảo lệnh sẽ khớp ở giá đã đặt."],"faq":[{"q":"Vì sao lệnh post-only của tôi bị hủy?","a":"Vì giá đặt sẽ khớp ngay với lệnh đối diện trong sổ, tức lệnh trở thành taker. Hãy đặt giá mua thấp hơn giá bán tốt nhất hoặc giá bán cao hơn giá mua tốt nhất."},{"q":"Post-only có giúp giảm phí không?","a":"Có, vì nó đảm bảo lệnh của bạn được tính phí maker. Mức phí maker cụ thể tùy sàn và cấp tài khoản."}],"title":"Lệnh post-only là gì? Cách đảm bảo phí maker","description":"Lệnh post-only là gì, vì sao giúp bạn luôn được phí maker, khi nào lệnh bị hủy và lúc nào không nên dùng.","related":[["maker-taker-fees","Phí maker và phí taker (Maker/Taker fee)","Phí maker và phí taker là hai mức phí giao dịch khác nhau: maker trả phí khi lệnh của bạn nằm chờ trên sổ lệnh và tạo thêm thanh khoản, taker trả phí khi lệnh của bạn khớp ngay với lệnh có sẵn."],["limit-order","Lệnh giới hạn (Limit order)","Lệnh giới hạn (limit order) là lệnh mua hoặc bán ở mức giá bạn chỉ định hoặc tốt hơn; lệnh chỉ khớp khi thị trường chạm mức giá đó, nếu không sẽ nằm chờ trong sổ lệnh."],["time-in-force","Hiệu lực lệnh (Time in force: GTC, IOC, FOK)","Time in force (hiệu lực lệnh) là thiết lập quy định một lệnh giới hạn tồn tại bao lâu và xử lý thế nào nếu không khớp ngay, phổ biến nhất là GTC, IOC và FOK."],["order-book","Sổ lệnh (Order book)","Sổ lệnh (order book) là danh sách theo thời gian thực của tất cả lệnh mua và lệnh bán đang chờ khớp cho một cặp giao dịch, sắp xếp theo mức giá và khối lượng."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Thị trường, giới hạn, hủy lệnh: mỗi loại giải quyết điều gì?"},"coin":null,"tool":"/rates","cta":false},"maker-taker-fees":{"slug":"maker-taker-fees","cat":"trading","en":"Maker and taker fees","contentLocale":"vi","term":"Phí maker và phí taker (Maker/Taker fee)","aka":["phí maker","phí taker","maker taker fee","phí giao dịch maker taker"],"short":"Phí maker và phí taker là hai mức phí giao dịch khác nhau: maker trả phí khi lệnh của bạn nằm chờ trên sổ lệnh và tạo thêm thanh khoản, taker trả phí khi lệnh của bạn khớp ngay với lệnh có sẵn.","body":[["Khi bạn đặt ",["lệnh giới hạn","limit-order"]," ở mức giá chưa khớp ngay, lệnh đó nằm trên ",["sổ lệnh","order-book"]," và chờ người khác khớp vào. Lúc này bạn là maker, tức người tạo ",["thanh khoản","liquidity"],". Khi bạn đặt ",["lệnh thị trường","market-order"],", hoặc lệnh giới hạn có giá khớp ngay với lệnh đang chờ, bạn là taker, tức người lấy thanh khoản đi."],["Hầu hết sàn tính phí maker thấp hơn phí taker để khuyến khích người dùng đặt lệnh chờ. Mức phí cụ thể khác nhau giữa các sàn, giữa spot và ",["hợp đồng tương lai","futures-contract"],", và thường giảm theo ",["cấp VIP","vip-tier"]," dựa trên khối lượng giao dịch hoặc số dư. Một số sàn còn giảm phí khi bạn dùng token của sàn để trả phí."],"Với người giao dịch thường xuyên, chênh lệch nhỏ giữa hai mức phí cộng dồn rất nhanh. Bạn nên xem bảng phí trên trang chính thức của sàn trước khi chọn kiểu lệnh."],"example":"Giả sử sàn tính phí maker 0,02% và phí taker 0,05% cho hợp đồng tương lai. Bạn mở một vị thế trị giá 20.000 USDT bằng lệnh thị trường: phí là 20.000 × 0,05% = 10 USDT. Nếu bạn dùng lệnh giới hạn và lệnh được khớp như maker, phí chỉ còn 20.000 × 0,02% = 4 USDT. Mở và đóng vị thế 50 lần mỗi tháng theo kiểu taker tốn khoảng 1.000 USDT phí, còn theo kiểu maker chỉ khoảng 400 USDT.","mistakes":["Nghĩ rằng mọi lệnh giới hạn đều được tính phí maker, trong khi lệnh giới hạn khớp ngay vẫn bị tính phí taker.","Chỉ nhìn phí mở vị thế mà quên rằng đóng vị thế cũng mất phí.","So sánh phí giữa các sàn mà không để ý mình đang ở cấp VIP nào và sản phẩm nào."],"faq":[{"q":"Phí maker và taker khác nhau thế nào?","a":"Maker là người đặt lệnh chờ trên sổ lệnh và thêm thanh khoản, taker là người khớp ngay với lệnh có sẵn. Phí maker thường thấp hơn phí taker."},{"q":"Làm sao để luôn được tính phí maker?","a":"Bạn có thể dùng lệnh Post Only. Lệnh này sẽ bị hủy nếu nó có thể khớp ngay, nên bạn luôn chỉ đóng vai maker."},{"q":"Phí maker có thể âm không?","a":"Có, một số sàn trả hoàn phí maker cho cấp VIP cao hoặc nhà tạo lập thị trường. Điều này tùy chính sách từng sàn."}],"title":"Phí maker và phí taker là gì? Cách tính phí giao dịch","description":"Tìm hiểu phí maker và phí taker là gì, vì sao phí maker thường rẻ hơn và cách tính phí cho mỗi lệnh crypto.","related":[["post-only-order","Lệnh chỉ đặt (Post-only)","Lệnh post-only là lệnh giới hạn chỉ được chấp nhận nếu nó nằm chờ trong sổ lệnh làm maker; nếu lệnh sẽ khớp ngay và trở thành taker, sàn tự động hủy hoặc điều chỉnh nó."],["limit-order","Lệnh giới hạn (Limit order)","Lệnh giới hạn (limit order) là lệnh mua hoặc bán ở mức giá bạn chỉ định hoặc tốt hơn; lệnh chỉ khớp khi thị trường chạm mức giá đó, nếu không sẽ nằm chờ trong sổ lệnh."],["market-order","Lệnh thị trường (Market order)","Lệnh thị trường (market order) là lệnh mua hoặc bán ngay lập tức ở giá tốt nhất hiện có trong sổ lệnh, ưu tiên tốc độ khớp thay vì kiểm soát giá."],["vip-tier","Cấp VIP (bậc phí giao dịch)","Cấp VIP là hệ thống bậc phí của sàn, trong đó người dùng có khối lượng giao dịch hoặc số dư tài sản lớn hơn được hưởng mức phí maker và taker thấp hơn."],["referral-code","Mã giới thiệu (hoàn phí giao dịch)","Mã giới thiệu là mã bạn nhập khi đăng ký sàn để liên kết tài khoản với người hoặc đối tác giới thiệu, thường giúp bạn được hoàn một phần phí giao dịch hoặc nhận ưu đãi người mới."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Tại sao giá trên màn hình không phải là giá khớp lệnh của tôi?"},"coin":null,"tool":"/rates","cta":true},"maintenance-margin":{"slug":"maintenance-margin","cat":"derivatives","en":"Maintenance margin","contentLocale":"vi","term":"Ký quỹ duy trì (Maintenance margin)","aka":["maintenance margin","MM","ký quỹ tối thiểu"],"short":"Ký quỹ duy trì là mức ký quỹ tối thiểu bạn phải giữ để vị thế có đòn bẩy không bị thanh lý.","body":[["Sàn tính ký quỹ duy trì bằng một tỷ lệ phần trăm của giá trị vị thế, ví dụ 0,5% cho bậc rủi ro thấp nhất. Khi số dư ký quỹ của vị thế, gồm cả ",["lãi lỗ chưa thực hiện","unrealized-pnl"]," theo ",["giá đánh dấu","mark-price"],", giảm xuống mức này, quá trình ",["thanh lý","liquidation"]," bắt đầu."],["Tỷ lệ ký quỹ duy trì tăng theo ",["quy mô vị thế","position-sizing"],". Vị thế càng lớn, sàn yêu cầu giữ tỷ lệ cao hơn vì thanh lý một vị thế lớn khó và tốn kém hơn. Đây là lý do ",["giá thanh lý","liquidation-price"]," của hai vị thế cùng ",["đòn bẩy","leverage"]," nhưng khác quy mô có thể khác nhau."],"Bạn có thể đẩy giá thanh lý ra xa bằng cách thêm ký quỹ vào vị thế cô lập hoặc giảm bớt khối lượng."],"example":"Giả sử bạn long 1 BTC ở 60.000 USDT với ký quỹ cô lập 6.000 USDT (10x). Tỷ lệ ký quỹ duy trì là 0,5%, tức 300 USDT. Vị thế bị thanh lý khi số dư còn 300 USDT, tức khi lỗ 5.700 USDT. Bỏ qua phí, giá thanh lý xấp xỉ 60.000 - 5.700 = 54.300 USDT. Nếu bạn thêm 2.000 USDT ký quỹ, giá thanh lý lùi xuống khoảng 52.300 USDT.","mistakes":["Nghĩ rằng vị thế chỉ bị thanh lý khi ký quỹ về 0.","Tính giá thanh lý theo giá giao dịch cuối thay vì giá đánh dấu.","Quên rằng vị thế lớn có tỷ lệ ký quỹ duy trì cao hơn."],"faq":[{"q":"Ký quỹ duy trì là gì?","a":"Là mức ký quỹ tối thiểu để vị thế còn mở. Khi số dư ký quỹ của vị thế xuống dưới mức này, sàn sẽ thanh lý."},{"q":"Làm sao tránh chạm ký quỹ duy trì?","a":"Dùng đòn bẩy thấp, đặt cắt lỗ trước giá thanh lý, hoặc thêm ký quỹ khi cần. Theo dõi tỷ lệ ký quỹ trong ứng dụng sàn."}],"title":"Ký quỹ duy trì (maintenance margin) là gì?","description":"Ký quỹ duy trì là gì, cách nó quyết định giá thanh lý và vì sao vị thế lớn cần tỷ lệ ký quỹ duy trì cao hơn.","related":[["initial-margin","Ký quỹ ban đầu (Initial margin)","Ký quỹ ban đầu là số tiền tối thiểu bạn phải đặt cọc để mở một vị thế có đòn bẩy, bằng giá trị vị thế chia cho đòn bẩy."],["liquidation-price","Giá thanh lý (Liquidation price)","Giá thanh lý là mức giá đánh dấu mà tại đó vị thế có đòn bẩy của bạn sẽ bị sàn tự động đóng do ký quỹ không còn đủ."],["margin-call","Margin call (Cảnh báo ký quỹ)","Margin call là cảnh báo từ sàn khi ký quỹ của bạn giảm gần mức ký quỹ duy trì, yêu cầu bạn nạp thêm ký quỹ hoặc giảm vị thế để tránh bị thanh lý."],["mark-price","Giá đánh dấu (Mark price)","Giá đánh dấu (mark price) là giá tham chiếu mà sàn dùng để tính lãi lỗ chưa thực hiện và quyết định thanh lý, được xây dựng từ giá chỉ số của nhiều sàn spot."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Tại sao bạn có thể bị đóng vị thế trước khi tiền ký quỹ về không?"},"coin":null,"tool":"/liquidations","cta":false},"reduce-only-order":{"slug":"reduce-only-order","cat":"derivatives","en":"Reduce-only order","contentLocale":"vi","term":"Lệnh chỉ giảm vị thế (Reduce-only)","aka":["reduce-only","reduce only","chỉ giảm"],"short":"Lệnh chỉ giảm vị thế (reduce-only) là tùy chọn khiến lệnh chỉ được phép đóng bớt hoặc đóng hết vị thế hiện có, không bao giờ mở thêm hay mở vị thế ngược chiều.","body":["Khi bật reduce-only, nếu khối lượng lệnh lớn hơn vị thế đang mở, sàn chỉ khớp phần tương ứng với vị thế hoặc tự điều chỉnh khối lượng. Nếu bạn không có vị thế, lệnh sẽ bị từ chối hoặc hủy.",["Tùy chọn này rất hữu ích cho ",["lệnh chốt lời","take-profit"]," và ",["cắt lỗ","stop-loss"]," đặt trước. Ví dụ, bạn đã đóng vị thế bằng tay nhưng quên hủy lệnh chốt lời; nếu lệnh đó không phải reduce-only, khi giá chạm nó có thể mở một vị thế mới ngoài ý muốn."],["Phần lớn lệnh TP/SL gắn vào vị thế trên các sàn đã tự là reduce-only, nhưng ",["lệnh giới hạn","limit-order"]," thường thì không. Hãy kiểm tra ô reduce-only khi đặt lệnh đóng."]],"example":["Giả sử bạn long 0,3 ",["BTC","bitcoin"]," và đặt lệnh bán giới hạn 0,3 BTC ở 72.000 ",["USDT","usdt"]," để chốt lời. Sau đó bạn đóng bằng tay 0,2 BTC ở 70.000, còn 0,1 BTC. Khi giá chạm 72.000, nếu lệnh là reduce-only, sàn chỉ bán 0,1 BTC và vị thế về 0. Nếu không bật, lệnh bán đủ 0,3 BTC, và bạn bất ngờ có ",["vị thế short","long-and-short"]," 0,2 BTC trị giá 14.400 USDT."],"mistakes":["Đặt lệnh chốt lời bằng lệnh giới hạn thường mà không bật reduce-only.","Quên hủy lệnh chờ sau khi đã đóng vị thế bằng tay.","Nghĩ rằng reduce-only đảm bảo lệnh được khớp, trong khi nó chỉ giới hạn hướng lệnh."],"faq":[{"q":"Reduce-only là gì?","a":"Là tùy chọn khiến lệnh chỉ đóng bớt vị thế hiện có. Lệnh sẽ không bao giờ mở vị thế mới hay tăng vị thế."},{"q":"Khi nào nên dùng reduce-only?","a":"Khi đặt lệnh chốt lời hoặc cắt lỗ bằng lệnh giới hạn hay lệnh dừng, để tránh vô tình mở vị thế ngược chiều."}],"title":"Reduce-only là gì? Lệnh chỉ giảm vị thế","description":"Lệnh reduce-only là gì, cách nó ngăn bạn vô tình mở vị thế ngược chiều và khi nào nên bật khi đặt chốt lời, cắt lỗ.","related":[["take-profit","Lệnh chốt lời (Take-profit)","Lệnh chốt lời (take-profit) là lệnh tự động đóng toàn bộ hoặc một phần vị thế khi giá đạt mức lợi nhuận bạn đặt trước, giúp bạn khóa lãi mà không cần theo dõi màn hình liên tục."],["stop-loss","Lệnh cắt lỗ (Stop-loss)","Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng."],["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["long-and-short","Long và Short (Vị thế mua và bán)","Long là mở vị thế kiếm lời khi giá tăng, short là mở vị thế kiếm lời khi giá giảm; hai thuật ngữ này dùng phổ biến trong giao dịch hợp đồng tương lai và ký quỹ."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Chốt lời và cắt lỗ là kế hoạch, không phải bảo hiểm"},"coin":null,"tool":null,"cta":false},"wallet-address":{"slug":"wallet-address","cat":"wallets-security","en":"Wallet address","contentLocale":"vi","term":"Địa chỉ ví (Wallet address)","aka":["wallet address","địa chỉ nhận","địa chỉ nạp"],"short":"Địa chỉ ví là chuỗi ký tự công khai đại diện cho nơi nhận crypto trên một blockchain cụ thể, giống số tài khoản ngân hàng nhưng gắn với từng mạng lưới.","body":[["Mỗi ",["blockchain","blockchain"]," có định dạng địa chỉ riêng: ",["Bitcoin","bitcoin"]," thường bắt đầu bằng bc1, 1 hoặc 3; ",["Ethereum","ethereum"],", BNB Chain, Arbitrum dùng chung dạng 0x; Tron bắt đầu bằng chữ T; Solana là chuỗi base58 không có tiền tố cố định. Cùng một dạng 0x có thể dùng trên nhiều mạng EVM, nên bạn phải chọn đúng mạng chứ không chỉ đúng địa chỉ."],"Giao dịch crypto không hoàn tác được. Gửi sai một ký tự thường bị ví từ chối nhờ mã kiểm tra, nhưng gửi đến một địa chỉ hợp lệ của người khác thì tiền đi luôn. Vì vậy hãy luôn sao chép thay vì gõ tay, và so sánh cả phần đầu lẫn phần cuối.","Trên sàn, địa chỉ nạp có thể đi kèm memo hoặc tag. Một số sàn cũng cấp địa chỉ nạp riêng cho từng mạng của cùng một đồng coin."],"example":["Giả sử bạn rút 300 ",["USDT","usdt"]," sang bạn bè. Họ gửi địa chỉ Tron TQ8m…4vXp. Bạn dán vào sàn, ",["chọn mạng","blockchain-network"]," TRC20 và so 4 ký tự đầu, 4 ký tự cuối đều khớp. Lần đầu bạn gửi thử 10 USDT, thấy bạn bè nhận được thì mới gửi 290 USDT còn lại. Bạn trả hai lần ",["phí rút","withdrawal-fee"]," nhưng tránh được rủi ro mất cả 300 USDT."],"mistakes":["Sao chép địa chỉ từ lịch sử giao dịch, nơi kẻ gian có thể cài địa chỉ gần giống.","Chỉ so vài ký tự cuối mà không kiểm tra phần đầu địa chỉ.","Dán địa chỉ 0x đúng nhưng chọn sai mạng, ví dụ người nhận chỉ hỗ trợ Ethereum mà bạn gửi qua BNB Chain."],"faq":[{"q":"Chia sẻ địa chỉ ví có an toàn không?","a":"An toàn về mặt chi tiêu, vì người khác chỉ có thể gửi tiền vào. Tuy nhiên ai có địa chỉ cũng xem được số dư và lịch sử giao dịch trên blockchain."},{"q":"Gửi nhầm địa chỉ có lấy lại được không?","a":"Thường là không, trừ khi chủ địa chỉ đó tự nguyện trả lại. Nếu gửi nhầm vào địa chỉ của một sàn, bạn có thể liên hệ sàn nhưng không có gì bảo đảm."}],"title":"Địa chỉ ví là gì? Cách kiểm tra trước khi chuyển","description":"Địa chỉ ví crypto là gì, định dạng trên từng blockchain, cách kiểm tra địa chỉ và tránh mất tiền khi gửi nhầm.","related":[["blockchain-network","Mạng nạp rút (Chọn mạng blockchain)","Mạng nạp rút là blockchain cụ thể mà một đồng coin được chuyển qua, ví dụ USDT có thể đi trên Tron (TRC20), Ethereum (ERC20) hay BNB Chain (BEP20); bên gửi và bên nhận phải dùng cùng mạng."],["memo-tag","Memo / Tag (Destination tag)","Memo hay tag là mã bổ sung đi kèm địa chỉ ví trên một số blockchain như XRP, XLM, TON, ATOM, giúp sàn biết khoản nạp vào địa chỉ chung thuộc về tài khoản nào."],["address-poisoning","Đầu độc địa chỉ (Address poisoning)","Đầu độc địa chỉ là chiêu lừa đảo gửi giao dịch nhỏ từ một địa chỉ có đầu và cuối giống địa chỉ bạn hay dùng, để bạn sao chép nhầm từ lịch sử giao dịch và chuyển tiền cho kẻ gian."],["withdrawal-whitelist","Danh sách trắng rút tiền (Withdrawal whitelist)","Danh sách trắng rút tiền là tính năng bảo mật chỉ cho phép tài khoản sàn rút crypto đến những địa chỉ bạn đã lưu và xác minh trước."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Trước khi chuyển coin: Tuyệt đối không đoán mò những điểm này"},"coin":null,"tool":null,"cta":false},"phishing":{"slug":"phishing","cat":"wallets-security","en":"Phishing","contentLocale":"vi","term":"Lừa đảo giả mạo (Phishing)","aka":["phishing","giả mạo","web giả","lừa đảo qua link"],"short":"Phishing là hình thức lừa đảo giả mạo sàn, ví, dự án hoặc người quen để lừa bạn nhập mật khẩu, mã 2FA, cụm từ khôi phục hoặc ký giao dịch có hại.","body":[["Phishing trong crypto có nhiều dạng: trang web có tên miền gần giống sàn thật, quảng cáo tìm kiếm dẫn đến app giả, email báo “tài khoản bị khóa”, tin nhắn Telegram từ “admin”, link “nhận ",["airdrop","airdrop"],"” trên mạng xã hội. Mục tiêu cuối cùng luôn là lấy thông tin đăng nhập, ",["cụm từ khôi phục","seed-phrase"],", hoặc khiến bạn ký một giao dịch cấp quyền rút token."],"Dấu hiệu nhận biết: thúc ép thời gian, hứa thưởng bất thường, tên miền sai một ký tự, yêu cầu nhập cụm từ khôi phục, hoặc ví hiện lệnh ký có nội dung khó hiểu như cấp quyền không giới hạn.",["Thói quen phòng tránh: tự gõ hoặc lưu bookmark địa chỉ sàn, chỉ tải app từ cửa hàng chính thức, bật ",["mã chống lừa đảo","anti-phishing-code"],", và đọc kỹ mọi yêu cầu ký trong ví."]],"example":["Giả sử bạn thấy bài đăng “Nhận 150 ",["USDT","usdt"]," airdrop, chỉ cần kết nối ví” kèm link trông giống trang của một dự án lớn. Bạn kết nối ví và được yêu cầu ký một lệnh “Permit”. Nếu bạn ký, trang có thể lấy toàn bộ 2.000 ",["USDC","usdc"]," trong ví. Bạn kiểm tra tên miền, thấy khác trang chính thức một chữ cái, nên đóng tab và không ký gì cả."],"mistakes":["Bấm vào link quảng cáo đầu tiên khi tìm tên sàn trên công cụ tìm kiếm.","Nhập cụm từ khôi phục vào trang tự xưng là “đồng bộ” hoặc “sửa lỗi” ví.","Ký lệnh trong ví mà không đọc nội dung chỉ vì trang web nói đó là bước “xác minh miễn phí”."],"faq":[{"q":"Làm sao biết trang web sàn là thật?","a":"Dùng bookmark hoặc địa chỉ bạn đã kiểm tra từ nguồn chính thức, so tên miền từng ký tự và kiểm tra mã chống lừa đảo trong email."},{"q":"Lỡ bấm link phishing nhưng chưa nhập gì thì có sao không?","a":"Thường rủi ro thấp nếu bạn không nhập thông tin, không tải file, không ký giao dịch. Hãy đóng trang và kiểm tra lại các quyền đã cấp trong ví cho chắc."}],"title":"Phishing là gì? Cách nhận biết lừa đảo giả mạo crypto","description":"Phishing trong crypto là gì, các dạng lừa đảo giả mạo sàn, ví, airdrop phổ biến và thói quen giúp bạn tránh mất tiền.","related":[["anti-phishing-code","Mã chống lừa đảo (Anti-phishing code)","Mã chống lừa đảo là chuỗi ký tự riêng bạn tự đặt trên sàn, sau đó sàn chèn nó vào mọi email chính thức để bạn phân biệt email thật với email giả mạo."],["seed-phrase","Cụm từ khôi phục (Seed phrase)","Cụm từ khôi phục là chuỗi 12 hoặc 24 từ tiếng Anh dùng để tạo lại toàn bộ khóa riêng tư của ví, nên ai có nó là có toàn quyền với tài sản trong ví."],["token-approval","Cấp quyền token (Token approval)","Cấp quyền token là thao tác cho phép một hợp đồng thông minh được chi tiêu một lượng token nhất định trong ví của bạn, bắt buộc trước khi swap hay gửi token vào nhiều ứng dụng DeFi."],["address-poisoning","Đầu độc địa chỉ (Address poisoning)","Đầu độc địa chỉ là chiêu lừa đảo gửi giao dịch nhỏ từ một địa chỉ có đầu và cuối giống địa chỉ bạn hay dùng, để bạn sao chép nhầm từ lịch sử giao dịch và chuyển tiền cho kẻ gian."],["pig-butchering-scam","Lừa đảo “nuôi heo” (Pig-butchering scam)","Lừa đảo “nuôi heo” là chiêu lừa kéo dài, kẻ gian làm quen, xây dựng lòng tin hoặc tình cảm qua mạng rồi dẫn nạn nhân vào nền tảng đầu tư crypto giả để rút sạch tiền."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Tìm đúng cửa chính thức: Đừng mở tài khoản một cách mù quáng"},"coin":null,"tool":null,"cta":false},"proof-of-reserves":{"slug":"proof-of-reserves","cat":"wallets-security","en":"Proof of reserves","contentLocale":"vi","term":"Bằng chứng dự trữ (Proof of reserves)","aka":["proof of reserves","PoR","bằng chứng tài sản"],"short":"Bằng chứng dự trữ là báo cáo sàn công bố để chứng minh họ đang nắm giữ đủ tài sản on-chain tương ứng với số dư khách hàng, thường kèm cách để từng người tự kiểm tra.","body":[["Sau sự sụp đổ của FTX năm 2022, nhiều sàn lớn bắt đầu công bố PoR. Phương pháp phổ biến gồm hai phần: danh sách ",["địa chỉ ví","wallet-address"]," của sàn để ai cũng xem được số dư on-chain, và cây Merkle tổng hợp số dư khách hàng để bạn kiểm tra tài khoản của mình có được tính vào tổng hay không."],"Tỷ lệ dự trữ được tính bằng tài sản sàn nắm giữ chia cho số dư khách hàng của từng coin. Tỷ lệ từ 100% trở lên nghĩa là tài sản ít nhất bằng số nợ với khách ở thời điểm chụp.","Hạn chế: PoR thường là ảnh chụp tại một thời điểm, có thể không thể hiện các khoản nợ khác của sàn, và chất lượng phụ thuộc vào bên kiểm toán. Hãy xem tần suất cập nhật, phạm vi coin và việc có bên thứ ba xác minh hay không."],"example":["Giả sử báo cáo PoR của một sàn ghi khách hàng gửi tổng 20.000 ",["BTC","bitcoin"],", còn ví on-chain của sàn chứa 20.600 BTC. Tỷ lệ dự trữ BTC là 20.600 chia 20.000, bằng 103%. Bạn nhập mã xác minh, thấy số dư 0,25 BTC của mình nằm trong cây Merkle. Nhưng nếu báo cáo ",["USDT","usdt"]," chỉ đạt 92%, đó là điểm đáng hỏi thêm."],"mistakes":["Coi PoR là bảo đảm tuyệt đối rằng sàn không thể gặp rủi ro.","Chỉ xem tỷ lệ tổng mà không xem tỷ lệ của đồng coin bạn đang gửi.","Dựa vào một báo cáo đã cũ nhiều tháng."],"faq":[{"q":"Sàn có PoR là an toàn tuyệt đối?","a":"Không. PoR cho thấy tài sản tại một thời điểm, nhưng không thay thế kiểm toán toàn diện về nợ phải trả và quản trị rủi ro."},{"q":"Làm sao tự kiểm tra PoR?","a":"Hầu hết sàn có trang PoR cho phép bạn kiểm tra số dư của mình trong cây Merkle và xem danh sách địa chỉ ví để đối chiếu trên trình khám phá khối."}],"title":"Proof of reserves là gì? Bằng chứng dự trữ của sàn","description":"Bằng chứng dự trữ (proof of reserves) là gì, cách sàn chứng minh tài sản, cách tự kiểm tra và giới hạn của PoR.","related":[["centralized-exchange","Sàn giao dịch tập trung (CEX)","Sàn giao dịch tập trung (CEX) là nền tảng do một công ty vận hành, giữ tài sản của người dùng và khớp lệnh mua bán trên sổ lệnh nội bộ, như Binance, OKX, Bybit hay Bitget."],["custodial-wallet","Ví lưu ký (Custodial wallet)","Ví lưu ký là ví mà một bên thứ ba, thường là sàn giao dịch, giữ khóa riêng tư thay bạn; bạn truy cập tài sản bằng tài khoản và mật khẩu thay vì seed phrase."],["insurance-fund","Quỹ bảo hiểm (Insurance fund)","Quỹ bảo hiểm là khoản dự trữ của sàn dùng để bù phần lỗ khi một vị thế bị thanh lý ở giá tệ hơn giá phá sản, nhằm tránh chuyển khoản lỗ đó sang người giao dịch khác."],["on-chain-analysis","Phân tích on-chain","Phân tích on-chain là việc đọc dữ liệu công khai trên blockchain như giao dịch, số dư ví và dòng tiền ra vào sàn để hiểu hành vi của người tham gia thị trường."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Tìm đúng cửa chính thức: Đừng mở tài khoản một cách mù quáng"},"coin":null,"tool":"/exchanges","cta":false},"crypto-earn":{"slug":"crypto-earn","cat":"exchange-features","en":"Crypto Earn (savings products)","contentLocale":"vi","term":"Earn (sản phẩm tiết kiệm crypto)","aka":["Crypto Earn","Simple Earn","tiết kiệm crypto","kiếm lãi crypto"],"short":"Earn là nhóm sản phẩm trên sàn cho phép bạn gửi crypto để nhận lãi, gồm gửi linh hoạt, gửi kỳ hạn, staking và các sản phẩm có cấu trúc.","body":["Mỗi sàn đặt tên khác nhau, như Simple Earn, Earn hay Savings, nhưng thường có hai loại cơ bản. Gửi linh hoạt cho phép rút bất kỳ lúc nào với lãi suất thay đổi. Gửi kỳ hạn khóa tài sản một số ngày nhất định với lãi suất thường cao hơn.",["Lãi đến từ nhiều nguồn: sàn cho người ",["giao dịch ký quỹ","margin-trading"]," vay, phần thưởng ",["staking","staking"]," trên chuỗi, hoặc các chiến lược khác. Vì vậy lãi suất hiển thị là ",["APR","apr-vs-apy"]," hoặc APY có thể thay đổi, và các mức lãi cao thường chỉ áp dụng cho một hạn mức nhỏ hoặc người dùng mới."],["Khi gửi Earn, tài sản do sàn lưu ký. Bạn chịu rủi ro sàn gặp sự cố, rủi ro giá của chính coin đó và rủi ro bị khóa nếu chọn kỳ hạn. Sản phẩm có cấu trúc như ",["đầu tư kép","dual-investment"]," có rủi ro khác hẳn gửi tiết kiệm."]],"example":["Giả sử bạn gửi 2.000 ",["USDT","usdt"]," vào sản phẩm kỳ hạn 30 ngày với APR 5%. Tiền lãi là 2.000 nhân 5% nhân 30 chia 365, khoảng 8,22 USDT. Nếu gửi linh hoạt với APR 3%, cùng 30 ngày bạn nhận khoảng 4,93 USDT nhưng có thể rút bất kỳ lúc nào. Nếu bạn gửi ",["BTC","bitcoin"]," thay vì USDT, giá trị quy ra USD còn phụ thuộc vào giá BTC, và biến động giá có thể lớn hơn nhiều so với tiền lãi."],"mistakes":["Thấy APR cao mà không đọc hạn mức áp dụng và thời gian khuyến mãi.","Gửi kỳ hạn số tiền có thể cần dùng gấp.","Coi sản phẩm có cấu trúc trong mục Earn là gửi tiết kiệm không rủi ro."],"faq":[{"q":"Lãi Earn trên sàn đến từ đâu?","a":"Thường từ cho vay ký quỹ, phần thưởng staking hoặc chiến lược của sàn. Mỗi sản phẩm ghi rõ nguồn lãi trong phần mô tả, hãy đọc trước khi gửi."},{"q":"Gửi Earn có an toàn như gửi ngân hàng không?","a":"Không giống nhau. Crypto trên sàn không có bảo hiểm tiền gửi như ngân hàng, và bạn chịu rủi ro của sàn lưu ký cũng như biến động giá."}],"title":"Crypto Earn là gì? Gửi tiết kiệm crypto trên sàn","description":"Earn là sản phẩm gửi crypto nhận lãi trên sàn. Phân biệt linh hoạt và kỳ hạn, nguồn lãi, cách tính APR và các rủi ro chính.","related":[["staking","Staking","Staking là việc khóa coin của một blockchain proof-of-stake để giúp xác thực giao dịch và bảo vệ mạng lưới, đổi lại nhận phần thưởng bằng chính coin đó."],["apr-vs-apy","APR và APY","APR là lãi suất năm chưa tính lãi kép, còn APY là lợi suất năm đã tính lãi kép; cùng một mức lãi, APY luôn bằng hoặc cao hơn APR nếu lãi được cộng dồn."],["dual-investment","Đầu tư kép (dual investment)","Đầu tư kép là sản phẩm có cấu trúc cho lợi suất cao trong thời gian ngắn, nhưng khi đáo hạn bạn có thể nhận lại tài sản ban đầu hoặc một tài sản khác tùy giá so với giá mục tiêu."],["custodial-wallet","Ví lưu ký (Custodial wallet)","Ví lưu ký là ví mà một bên thứ ba, thường là sàn giao dịch, giữ khóa riêng tư thay bạn; bạn truy cập tài sản bằng tài khoản và mật khẩu thay vì seed phrase."]],"lesson":null,"coin":null,"tool":"/activities","cta":true},"p2p-trading":{"slug":"p2p-trading","cat":"exchange-features","en":"P2P (C2C) trading","contentLocale":"vi","term":"Giao dịch P2P (C2C)","aka":["P2P","C2C","mua bán P2P","chợ P2P"],"short":"Giao dịch P2P là hình thức mua bán crypto trực tiếp giữa hai người dùng trên một nền tảng, trong đó sàn giữ coin của người bán làm bảo đảm cho tới khi người mua thanh toán xong.","body":[["Người bán đăng quảng cáo với giá, hạn mức và phương thức thanh toán như chuyển khoản ngân hàng. Người mua đặt lệnh, coin của người bán được khóa trong ký quỹ của sàn. Người mua chuyển tiền rồi bấm ",["xác nhận","block-confirmations"]," đã thanh toán, người bán kiểm tra tài khoản và thả coin."],["P2P là kênh phổ biến để mua bán ",["USDT","usdt"]," bằng VND. Giá do người dùng tự đặt nên có thể cao hoặc thấp hơn tỷ giá thị trường một chút. Sàn thường không thu phí người mua, nhưng chính sách phí với người đăng quảng cáo khác nhau."],"Rủi ro thường gặp là lừa đảo: người mua gửi ảnh chuyển khoản giả, dùng tiền bẩn từ tài khoản bên thứ ba, hoặc dụ bạn giao dịch ngoài nền tảng. Chỉ thả coin khi tiền đã thực sự vào tài khoản, từ tài khoản trùng tên người mua."],"example":"Giả sử bạn bán 400 USDT trên P2P với giá 25.800 đồng, người mua phải chuyển 10.320.000 đồng. Họ bấm đã thanh toán và gửi ảnh chụp màn hình. Bạn mở ứng dụng ngân hàng thì chưa thấy tiền. Bạn không thả coin, chờ thêm và kiểm tra lại. Nếu tiền vẫn không về trước khi lệnh hết hạn, bạn mở khiếu nại trong ứng dụng sàn. Coin vẫn nằm trong ký quỹ nên không mất.","mistakes":["Thả coin chỉ dựa vào ảnh chụp chuyển khoản thay vì kiểm tra tài khoản ngân hàng.","Nhận tiền từ tài khoản không trùng tên với người mua trên sàn.","Đồng ý chuyển sang nói chuyện và giao dịch qua Telegram hay Zalo ngoài nền tảng."],"faq":[{"q":"P2P và C2C có khác nhau không?","a":"Hai từ thường được dùng thay cho nhau, đều chỉ việc mua bán trực tiếp giữa người dùng với sàn làm trung gian ký quỹ."},{"q":"Mua USDT qua P2P có an toàn không?","a":"Khá an toàn nếu bạn giao dịch trong nền tảng, chọn người bán có nhiều đánh giá tốt và chuyển khoản đúng thông tin trong lệnh. Rủi ro tăng mạnh khi giao dịch ngoài nền tảng."}],"title":"P2P là gì? Cách mua bán USDT P2P an toàn","description":"Giao dịch P2P là mua bán crypto trực tiếp với ký quỹ của sàn. Hướng dẫn quy trình, cách tránh lừa đảo và tiền bẩn khi mua USDT.","related":[["fiat-on-ramp","Cổng nạp tiền pháp định (fiat on-ramp)","Cổng nạp tiền pháp định là dịch vụ cho phép bạn đổi tiền như VND hay USD thành crypto, qua chuyển khoản ngân hàng, thẻ, ví điện tử hoặc giao dịch P2P."],["usdt","USDT (Tether)","USDT là stablecoin do công ty Tether phát hành, neo theo tỷ lệ 1 USDT bằng 1 USD và là đồng ổn định được giao dịch nhiều nhất trên các sàn crypto."],["pig-butchering-scam","Lừa đảo “nuôi heo” (Pig-butchering scam)","Lừa đảo “nuôi heo” là chiêu lừa kéo dài, kẻ gian làm quen, xây dựng lòng tin hoặc tình cảm qua mạng rồi dẫn nạn nhân vào nền tảng đầu tư crypto giả để rút sạch tiền."],["kyc","KYC (xác minh danh tính khách hàng)","KYC là quy trình sàn giao dịch hoặc tổ chức tài chính xác minh danh tính người dùng bằng giấy tờ tùy thân, ảnh khuôn mặt và đôi khi là địa chỉ cư trú."]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"Lần nạp tiền đầu tiên: Tiền đến từ đâu và đi về đâu?"},"coin":null,"tool":null,"cta":true}});
